def robust_prune(p, cands, alpha, R, dist, out_nbrs):
    V = (set(cands) | set(out_nbrs[p])) - {p}
    new = []
    while V:
        p_star = min(V, key=lambda v: dist(p, v))
        new.append(p_star)
        if len(new) == R:
            break
        V = {v for v in V if alpha * dist(p_star, v) > dist(p, v)}
    out_nbrs[p] = new
